// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2005, "8-9", [{"author":"Н. Валеева","question":"Посмотрите на слова корова, овца, собака, волк и решите, что лишнее:","choices":["отара","стадо","табун","стая","свора"],"key":"В","review":["Кто держится табуном","Стадом называют коров, отарой — овец, сворой — собак, стаей — волков.","Табуном называют группу лошадей. Лошадей среди перечисленных животных нет."]},{"author":"Е. Дмитриева","question":"Как известно, брата Анны Карениной звали Стива Облонский. С каким русским именем соотносится английское личное имя <em>Стив, Стивен</em>?","choices":["<em>Станислав</em>","<em>Ростислав</em>","<em>Степан</em>","<em>Устин</em>","<em>Евстигней</em>."],"key":"В","review":["Русская форма имени","Стива — домашняя форма имени Степан у Облонского. Английские Steve и Steven — формы того же имени.","Они восходят к греческому Stéphanos. Русский вариант в списке — Степан."]},{"author":"И. Рубанов","question":"Известное детское стихотворение начинается строками:\nМы делили апельсин.\nМного нас, а он — один.\nВот список слов: лимон, мандарин, георгин, барабан, блин, бензин, магазин. Сколькими из них можно заменить в этом двустишии слово апельсин, не нарушая рифмы и размера исходного стихотворения?","choices":["одним","двумя","тремя","четырьмя","пятью."],"key":"В","review":["Рифма и три слога","На месте «апельсин» нужно слово из трёх слогов с ударением на последнем и окончанием, рифмующимся с «один».","Подходят «мандарин», «георгин» и «магазин». Например, «бензин» рифмуется, но в нём два слога."]},{"author":"Б. Иомдин","question":"Сходство слов по звучанию часто приводит к орфографическим ошибкам. Какое из этих слов написано правильно?","choices":["<em>нечайно</em>","<em>отчайно</em>","<em>случаянно</em>","<em>необычайно</em>","<em>черезвычайно</em>."],"key":"Г","review":["Проверяем написание","Верные написания: «нечаянно», «отчаянно», «случайно», «необычайно», «чрезвычайно».","С предложенным вариантом совпадает только «необычайно»."]},{"author":"Е. Муравенко","question":"В четырёх ребусах зашифровано одно и то же слово, а в одном — другое. В каком?","choices":["Ребус А","Ребус Б","Ребус В","Ребус Г","Ребус Д"],"key":"В","review":["Слова в пяти ребусах","В ребусе В начало «с К О» получается из букв, стоящих вместе. От «рот» убираем последнюю букву, от «кисть» — две первые.","Выходит «ско-ро-сть». В других ребусах зашифрована «сковорода»."],"figure":{"options":[{"src":"assets/medvezhonok/2005/8-9-05-rebus-1.webp","pixelWidth":305,"pixelHeight":82,"description":"Танцующие К и О, Р внутри О и формула воды с запятой."},{"src":"assets/medvezhonok/2005/8-9-05-rebus-2.webp","pixelWidth":218,"pixelHeight":83,"description":"Фигуры букв, две секции ограды и замена Т на Д."},{"src":"assets/medvezhonok/2005/8-9-05-rebus-3.webp","pixelWidth":248,"pixelHeight":78,"description":"К и О, рот с запятой справа, кисть с двумя запятыми слева."},{"src":"assets/medvezhonok/2005/8-9-05-rebus-4.webp","pixelWidth":271,"pixelHeight":84,"description":"Дерево с птицей, вложенные буквы, цветок и замена З на Д."},{"src":"assets/medvezhonok/2005/8-9-05-rebus-5.webp","pixelWidth":262,"pixelHeight":83,"description":"Нота, кастрюля и жук с запятыми."}]}},{"author":"Н. Валеева","question":"Даны существительные <em>платье</em>, <em>устье</em>, <em>копьё</em>. Заменим у каждого из них окончание на -<em>ев</em>: <em>платьев</em>, <em>устьев</em>, <em>копьев</em>. Какие из этих слов будут правильными формами родительного падежа множественного числа?","choices":["все","<em>платьев</em> и <em>устьев</em>","<em>платьев</em> и <em>копьев</em>","только <em>платьев</em>","только <em>копьев</em>."],"key":"Б","review":["Формы после «много»","Говорят «много платьев» и «много устьев». Обе формы на -ев нормативны.","От «копьё» образуется «копий». Форма «копьев» не соответствует литературной норме."]},{"author":"Е. Муравенко","question":"Во всех данных словах, кроме одного, можно переставить буквы так, что получатся названия животных. Кроме какого?","choices":["<em>банка</em>","<em>крона</em>","<em>скала</em>","<em>шкала</em>","<em>шпала</em>."],"key":"Д","review":["Звери из тех же букв","Из «банка» получается «кабан», из «крона» — «норка», из «скала» — «ласка», из «шкала» — «шакал».","У «шпала» среди перестановок нет обычного названия животного. Это исключение."]},{"author":"И. Иткин","question":"Некоторые существительные имеют в предложном падеже, кроме обычной формы, ещё и особую. Например, <em>на переднем крае</em> и <em>на краю гибели</em>. А какое из следующих слов не имеет в литературном языке особой формы предложного падежа на –<em>у</em> /-<em>ю</em>?","choices":["<em>корень</em>","<em>бред</em>","<em>круг</em>","<em>пляж</em>","<em>строй.</em>"],"key":"Г","review":["Окончание со значением места","Есть «на корню», «в бреду», «в кругу» и «в строю». Это особые предложные формы на -у или -ю.","На берегу говорят «на пляже». Особая форма «на пляжу» литературной нормой не предусмотрена."]},{"author":"Е. Русинова","question":"Если удвоить слог <em>ма</em>, получится слово <em>мама</em>, из слога <em>па — папа</em>. Посмотрите на слоги и решите, из какого не получится нового слова.","choices":["<em>вар</em>","<em>пур</em>","<em>киш</em>","<em>кан</em>","<em>там</em>."],"key":"В","review":["Удвоение и новое слово","«Варвар», «пурпур», «канкан» и «тамтам» состоят из двух повторённых частей.","Из «киш» вышло бы «кишкиш», а такого слова нет. Слово «кишки» не является точным удвоением."]},{"author":"Б. Иомдин","question":"Даны слова: <em>бор, вина, вино, вор, дело, дом, мешок, плод, яд.</em> Сколько из них образуют прилагательные с суффиксом <em>-овит</em>-?","choices":["3","4","5","6","8."],"key":"Б","review":["Суффикс «-овит-»","От «дело», «дом», «плод» и «яд» образованы «деловитый», «домовитый», «плодовитый» и «ядовитый».","От «вор» обычно говорят «вороватый», от «вина» — «виноватый». Нужный суффикс есть ровно в четырёх словах."]},{"author":"Е. Русинова","question":"В романе А. С. Пушкина «Евгений Онегин» встречается слово <em>немудрено</em>. Например,\n\nМы все учились понемногу\nЧему-нибудь и как-нибудь,\nТак воспитаньем, слава богу,\nУ нас немудрено блеснуть…\n\nТам будет бал, там детский праздник.\nКуда ж поскачет мой проказник?\nС кого начнёт он? Всё равно:\nВезде поспеть немудрено…\n\nА что оно означает?","choices":["‘невозможно’","‘непросто’","‘можно’","‘нетрудно’","‘не суждено’."],"key":"Г","review":["Как понимать «немудрено»","В обоих отрывках автор говорит, что при известных условиях легко блеснуть или везде успеть.","«Немудрено» значит «нетрудно»: для этого не нужно особой мудрости или большого усилия."]},{"author":"Е. Муравенко","question":"Вот несколько существительных: <em>круг, площадь, катет, гипотенуза, произведение, дробь</em>. Сколько из них являются не только математическими терминами?","choices":["одно","два","три","четыре","пять."],"key":"Г","review":["Термин вне математики","Круг бывает кругом друзей, площадь — городской площадью, произведение — литературным, дробь — мелкими шариками для стрельбы.","«Катет» и «гипотенуза» в обычном употреблении геометрические термины. Нематематических значений в списке четыре."]},{"author":"Е. Муравенко","question":"Даны пары слов. В какой из них слова состоят из одинаковых звуков?","choices":["<em>друг</em> — <em>гурт</em>","<em>сруб</em> — <em>брус</em>","<em>стиль</em> — <em>лист</em>","<em>гроздь</em> — <em>горсть</em>","<em>шов</em> — <em>вошь</em>."],"key":"Г","review":["Оглушение и перестановка","«Гроздь» произносится [грос’т’]: перед мягким оглушённым [т’] слышно [с’]. В «горсть» слышно [горс’т’].","Набор звуков одинаковый, [р] и [о] меняются местами. В других парах есть звуки с другим местом образования, звонкостью или мягкостью."]},{"author":"И. Рубанов","question":"Через два часа после отхода поезд был в ... от Петербурга.","choices":["полуторастах километрах","полуторах стах километрах","полуторах стах километров","полуторастах километров","полутораста километрах."],"key":"Д","review":["Склонение «полтораста»","Число 150 в именительном и винительном — «полтораста». Для остальных падежей используется «полутораста».","После «в» со значением расстояния нужен предложный падеж: «в полутораста километрах»."]},{"author":"Б. Иомдин","question":"Какие буквы нужно вставить в строку из песни Владимира Высоцкого, чтобы она была записана правильно?\nЯ узнал старика по слезам на щеках его дряблых:\nЭто Пётр Святой — он _п_ст_л, а я — _ст_л_п.","choices":["<em>о, о, о, о, о, о</em>","<em>а, о, а, о, а, о</em>","<em>а, о, о, о, о, о</em>","<em>о, о, а, а, а, о</em>","<em>а, о, а, о, о, о.</em>"],"key":"В","review":["Два слова из песни","В песне о Петре Святом подходит «апостол». Оно пишется с а и двумя о.","Рассказчик называет себя «остолопом», то есть глупцом. Здесь три о. Порядок букв: а, о, о, о, о, о."]},{"author":"В. Борун","question":"Фирма «Гигазвон» хранит тексты клиентов. Ниже даны фразы, которые могли бы быть сказаны клиентами этой фирмы.\n1. Представляешь, я ту лекцию сунул на гигу, думал, возьму с гиги перед экзаменом, а теперь оказалось, что на гиге ничего не сохранилось.\n2. Представляешь, я ту лекцию сунул на гигу, думал, возьму из гиги перед экзаменом, а теперь оказалось, что на гиге ничего не сохранилось.\n3. Представляешь, я ту лекцию сунул в гигу, думал, возьму из гиги перед экзаменом, а теперь оказалось, что в гиге ничего не сохранилось.\n4. Представляешь, я ту лекцию сунул в гигу, думал, возьму с гиги перед экзаменом, а теперь оказалось, что в гиге ничего не сохранилось.\nМы не спрашиваем вас, что такое гига, но утверждаем, что независимо от значения этого слова две из этих фраз наверняка построены неправильно. Какие?","choices":["2 и 3","1 и 2","1 и 3","1 и 4","2 и 4"],"key":"Д","review":["Направление туда и обратно","К «на» при движении в обратную сторону подходит «с»: на полку — с полки. К «в» подходит «из»: в ящик — из ящика.","Фразы 2 и 4 смешивают эти пары. Значение «гиги» для проверки не требуется."]},{"author":"И. Рубанов","question":"Теорема доказывается, беседуя с учениками.\nТеорему доказывают, беседуя с учениками.\nТеорема доказана, беседуя с учениками.\nТеорема была доказана, беседуя с учениками.\nТеорему докажут, беседуя с учениками.\nТеорема доказана в беседе с учениками.\nСколько среди этих фраз неправильно построенных?","choices":["одна","две","три","четыре","пять."],"key":"В","review":["Кто ведёт беседу","Деепричастие «беседуя» должно относиться к тем же действующим лицам, которые доказывают теорему. Это возможно в «теорему доказывают» и «теорему докажут».","В первой, третьей и четвёртой фразах грамматическое подлежащее — сама теорема. Она беседовать не может. Ошибок три."]},{"author":"И. Иткин","question":"В уйгурском языке, как и в некоторых других тюркских языках, слово <em>ат</em> означает ‘лошадь’. А что означает в уйгурском языке слово <em>атхана</em>?","choices":["‘любимая лошадь хана’","‘конюшня’","‘пони’","‘конокрад’","‘никотин’."],"key":"Б","review":["Место для лошадей","Уйгурское «ат» значит «лошадь». Элемент «хана» обозначает помещение, как в слове «чайхана».","Сочетание обозначает помещение для лошадей — конюшню."]},{"author":"И. Иткин","question":"В «Песни о вещем Олеге» А. С. Пушкина читаем: <em>И пращ, и стрела, и лукавый кинжал Щадят победителя годы.</em> Соответствует ли современным нормам употреблённая Пушкиным форма <em>пращ</em>?","choices":["да, соответствует","нет, правильно <em>пращь</em>","нет, правильно <em>прáща</em>","нет, правильно <em>пращá</em>","нет, в современном русском языке вообще нет такого слова."],"key":"Г","review":["Старинная форма «пращ»","В стихе «пращ» — название оружия для метания камней, которое Пушкин употребил в старой форме.","Сегодня нормативное слово «праща́», женского рода, с ударением на последнем слоге."]},{"author":"Н. Валеева","question":"Какое из этих слов не является производным?","choices":["<em>бомж</em>","<em>морж</em>","<em>вуз</em>","<em>нэп</em>","<em>загс</em>."],"key":"Б","review":["Слово или сокращение","Бомж, вуз, нэп и загс возникли как сокращения словосочетаний.","«Морж» — самостоятельное название животного. Оно не составлено из начальных букв других слов."]},{"author":"С. Бурлак","question":"Даны словосочетания, реально встретившиеся в различных текстах: 1) <em>бегущая строка</em>, 2) <em>вот-вот подешевеющий «Москвич»</em>, 3) <em>соответствовавшие бы друг другу формы</em>, 4) <em>раскрасневшееся лицо</em>. В каких из них нарушены нормы русского языка?","choices":["в первом и втором","во втором и третьем","только во втором","только в третьем","во всех."],"key":"Б","review":["Причастия и время","«Бегущая строка» и «раскрасневшееся лицо» — обычные причастия настоящего и прошедшего времени.","«Подешевеющий» пытается образовать причастие будущего времени, а «соответствовавшие бы» — условного наклонения. В норме, принятой в конкурсе, нужны другие конструкции."]},{"author":"Б. Иомдин","question":"Левый приток Днепра предположительно получил название Десна в VI–VII вв., когда славянские племена переселялись по Днепру на север. По мнению учёных, это название связано с тем, что:","choices":["Десна находится слева от Днепра, если стоять лицом к северу","Десна находится справа от Днепра, если стоять лицом к северу","место слияния Десны и Днепра напоминает очертаниями зуб","Десна была десятой по счёту рекой, которая встретилась переселенцам","это сокращение фразы: <em>Днепр есть с нами!</em>"],"key":"Б","review":["С какой стороны течёт река","Название связывают со старым «десный», то есть правый, как в слове «десница».","Если двигаться по Днепру на север, Десна окажется справа. Обозначение «левый приток» определяют, глядя вниз по течению."]},{"author":"И. Иткин и Л. Иткина","question":"Есть такая игра: один из играющих загадывает нарицательное существительное в словарной форме, указывая его первую и последнюю букву, а также количество букв между ними, а другие должны его отгадать. Например, для последовательности <em>к _ _ ч</em> отгадкой могут быть два существительных — <em>клич</em> и <em>ключ</em>. Сколько нарицательных существительных в словарной форме могут быть отгадкой для последовательности <em>х _ _ м</em>?","choices":["ни одного","одно","два","три","четыре."],"key":"Д","review":["Две буквы внутри рамки","Подбираем обычные словарные существительные из четырёх букв: между х и м могут стоять «ра», «ла», «ол», «ро».","Получаются «храм», «хлам», «холм» и «хром». Всего четыре."]},{"author":"И. Иткин","question":"Фамилии знаменитых лётчиков Ивана Кожедуба и Валентины Гризодубовой происходят от прозвищ <em>Кожедуб</em> и <em>Гризодуб</em> (последнее, видимо, имеет украинское происхождение, но догадаться о его значении несложно). Даны слова <em>дуболом</em> и <em>лизоблюд</em>. По какой модели образованы прозвища <em>Кожедуб</em> и <em>Гризодуб</em>?","choices":["по той же модели, что и слово <em>дуболом</em>","по той же модели, что и слово <em>лизоблюд</em>","<em>Кожедуб</em> — по той же модели, что <em>дуболом</em>, <em>Гризодуб</em> — по той же модели, что <em>лизоблюд</em>","<em>Кожедуб</em> — по той же модели, что <em>лизоблюд</em>, <em>Гризодуб</em> — по той же модели, что <em>дуболом</em>","ни один из ответов (А)–(Г) не верен."],"key":"В","review":["Порядок частей прозвища","«Дуболом» сначала называет предмет, дуб, затем действие, ломать. Так же «кожедуб» сначала называет кожу, которую дубят.","«Лизоблюд» начинается с действия, как «Гризодуб», то есть «грызёт дуб». Верна пара в варианте В."]},{"author":"И. Иткин","question":"У знаменитой строки А. С. Пушкина <em>И долго буду тем любезен я народу</em> существует юмористическая переделка: <em>И долго буду тем любезен я и этим</em>. Сколько различных пониманий допускает эта шуточная фраза?","choices":["ни одного — эта фраза совершенно бессмысленна","одно","два","три","четыре."],"key":"Д","review":["Четыре чтения строки","«Тем» может означать «тем людям» или «тем обстоятельством». «Этим» так же означает «этим людям» или «этим обстоятельством».","Независимый выбор для двух слов даёт четыре толкования. В обоих случаях возможны адресаты, причины и их сочетания."]},{"author":"С. Переверзева","question":"Даны слова <em>рассвет, ворчун, кровь</em>. Какое из них не может быть подлежащим при сказуемом <em>бр...зжит</em>?","choices":["<em>рассвет</em>","<em>ворчун</em>","<em>кровь</em>","никакое","все могут быть."],"key":"В","review":["Похожие по звучанию глаголы","Рассвет брезжит, то есть едва светится. Ворчун брюзжит, то есть недовольно ворчит.","Кровь брызжет, где после «бр» нужна ы и после з пишется ж, а не второе з. Данный написанный шаблон не подходит."]},{"author":"И. Иткин","question":"Перед Вами — две цитаты из романа А. С. Пушкина «Евгений Онегин»:\nИ вы, читатель благосклонный,\nВ своей коляске выписной...\n\nМеж тем как сельские циклопы\nПеред медлительным огнём\nРоссийским лечат молотком\nИзделье лёгкое Европы...\nЧто означает в первой из приведённых цитат прилагательное <em>выписной</em>?","choices":["богато изукрашенный","неспособный ехать прямо","принадлежащий титулованной особе","с документально оформленным правом на владение","привезённый из-за границы."],"key":"Д","review":["Коляска из Европы","«Выписать» может означать заказать доставку из другого места. Вторая цитата уточняет происхождение изделия.","Коляска — «изделье лёгкое Европы», то есть привезённая из-за границы."]},{"author":"С. Бурлак","question":"Диалектологи, исследовавшие речь Клавдии Васильевны из деревни Савино Ивановской области, записали такие фразы: <em>Шампуни не было, я мыло купила</em>; <em>Сегодня новую толь привезли</em>, <em>крышу крыть</em>; <em>Смотри, на тюли моль сидит</em>! Изучив отличия диалекта, на котором говорит Клавдия Васильевна, от литературной нормы, диалектологи совершенно не удивились, услышав от неё:","choices":["<em>Они с путя сбились.</em>","<em>Он ничего путью не знает!</em>","<em>Не ложьте шапку на стол!</em>","<em>А куды ее покласть?</em>","<em>Не ходи туды!</em>"],"key":"Б","review":["Род в деревенской речи","Говорящая употребляет «шампунь», «толь» и «тюль» как существительные женского рода. Например, «новую толь».","Такая же закономерность допускает форму «путью» у слова «путь». Остальные варианты показывают другие диалектные явления."]},{"author":"П. Аркадьев","question":"Даны узбекские слова и их переводы на русский язык: ota — <em>отец</em>, otam — <em>мой отец</em>, otang — <em>твой отец</em>, gazetalarim — <em>мои газеты</em>, otamiz — <em>наш отец</em>, gazetalaring — <em>твои газеты</em>. Как будет по-узбекски <em>ваш отец</em>, <em>ваши газеты</em>, <em>отцы</em>?","choices":["otangiz, gazetalaringlar, otaiz","otanglar, gazetalaringiz, otalar","otalaring, gazetalarizing, otalar","otangiz, gazetalaringiz, otalar","otamiz, gazetalarimiz, otalar."],"key":"Г","review":["Два узбекских суффикса","В gazetalar- виден суффикс множественного числа -lar: «отцы» будет otalar. Сопоставление «мой — наш» даёт добавку -iz.","От otang «твой отец» получаем otangiz «ваш отец», от gazetalaring — gazetalaringiz «ваши газеты»."]},{"author":"Б. Иомдин","question":"Известно, что заимствованные слова усваиваются языком постепенно и могут впоследствии менять свои грамматические характеристики. Какое слово мы пропустили в отрывке из «Песни московского извозчика» (слова Ярослава Родионова)? <em>\nНо ___________, сверкнув перилами дубовыми,\nСразу всех он седоков околдовал</em>.","choices":["<em>автобус</em>","<em>троллейбус</em>","<em>трамвай</em>","<em>метро</em>","<em>такси</em>."],"key":"Г","review":["Род слова в старой песне","Перила и седоки указывают на транспорт. В песне речь о московском метро.","Раньше слово связывали с мужским «метрополитен», поэтому возможно «он». В современной норме «метро» среднего рода."]}], {"year":2005,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"8-9-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2005.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
